    'Итоговый лимит пересчитывается после изменения framework, функций, технологий и команды.':
        'The final limit is recalculated after changing the framework, functions, technologies, and command.',
    'К продукту можно подключить одну корпоративную AI. Она ускоряет разработку, повышает quality и добавляет постоянную нагрузку на серверы.':
        'One enterprise AI can be connected to the product, which speeds up development, improves quality, and adds a constant load on the servers.',
    'Каждая пара хранится один раз. Связь даёт конкретный эффект, стоимость, срок и риск.':
        'Each pair is stored once, and the connection has a specific effect, cost, time and risk.',
    'Каждая сущность сериализуется без временных UI-полей.':
        'Each entity is serialized without temporary UI fields.',
    'Каждое подключение стоит 45 000 ₽ в месяц.':
        'Each connection costs 45,000 ₽ per month.',
    'Каждому типу продукта нужны конкретные специальности. Нанятый сотрудник работает только на том продукте, куда назначен в «Операциях».':
        'Each type of product needs a specific specialty, and the employee only works on the product he or she is assigned to in Operations.',
    'Каждый внешний интеграционный риск получает fallback и наблюдаемую ошибку.':
        'Every external integration risk gets a fallback and an observable error.',
    'Каждый заказ имеет отдельную команду, прогресс и дедлайн.':
        'Each order has a separate team, progress and deadline.',
    'Каждый заказ теперь ведётся как отдельный проект со своей командой, сроком и карточкой.':
        'Each order is now conducted as a separate project with its own team, deadline and card.',
    'Каждый инвестор имеет свой фокус, лимит и готовность к риску.':
        'Every investor has a focus, a limit, and a willingness to take risks.',
    'Каждый контроль имеет разовую стоимость внедрения, ежемесячную стоимость и точный коэффициент снижения вероятности инцидента.':
        'Each control has a one-off cost of implementation, a monthly cost, and an exact factor to reduce the likelihood of an incident.',
    'Каждый продукт имеет собственную нагрузку и отдельную выручку.':
        'Each product has its own load and separate revenue.',
    'Каждый профиль генерируется при появлении на рынке. Грейд задаёт диапазон характеристик и зарплаты, а конкретные значения случайны. Имя в рамках одной игры не переиспользуется. Remote-сотрудник не занимает место в офисе.':
        'Each profile is generated when it enters the market. Grade sets a range of characteristics and salaries, and the specific values are random. The name in one game is not reused. The Remote employee does not take up a seat in the office.',
