    'Мощность разработки не является отдельным ресурсом или серверной мощностью. Это производительность людей. При работе сотрудника над несколькими проектами его вклад делится между ними, а перегрузка снижает мораль.':
        'Development power is not a single resource or server power, it\'s people\'s productivity, and when you\'re working on multiple projects, your contribution is shared, and overload reduces morale.',
    'Мощность разработки учитывает не только средние навыки, но и покрытие обязательных ролей. Один сильный Backend-разработчик не заменяет безопасность, дизайн или QA.':
        'Development power takes into account not only mid-skills, but also the coverage of required roles: One strong backend developer does not replace security, design or QA.',
    'Мощность разработки — эффективная скорость команды в FTE. 1,0 FTE примерно равен одному подходящему специалисту на полной занятости. Значение учитывает навыки, роль, языки, долю времени, мораль и AI-помощь.':
        'Development power is the effective speed of a team in FTE. 1.0 FTE is roughly equal to one suitable full-time professional. Value takes into account skills, role, languages, time share, morals and AI assistance.',
    'Мультимодальный ввод': 'Multimodal input',
    'На арендном hosting работают мощности тарифа. Купленные серверы находятся в резерве и начнут учитываться только после явной миграции на собственную инфраструктуру.':
        'Rental hosting is powered by the tariff, and the servers purchased are in reserve and will be counted only after an obvious migration to their own infrastructure.',
