    'Первая неделя в минусе — время исправить экономику. После недели банк может предложить кредит. Повторный минус при погашении менее 70% приводит к банкротству; после 70% доступна последняя неделя.':
        'The first week in the negative is the time to fix the economy. After a week, the bank can offer a loan. Repeated minus on repayment of less than 70% leads to bankruptcy; after 70%, the last week is available.',
    'Первые 21 игровой день после обновления продукт считается свежим. Затем штраф растёт постепенно. Любая крупная функция или техническое улучшение обновляет дату свежести.':
        'The first 21 game days after the product update are considered fresh. The penalty then increases gradually. Any major feature or technical improvement updates the freshness date.',
